        var sourceSlices=sources.stream().map(a->a.get("stock_slice_id")).filter(Objects::nonNull).map(StorageLedgerService::id).distinct().toList();
        if(sourceSlices.size()>1)throw fail("原领料涉及多个批次份额，请按实际来源逐项退料");
