        var returnedResult=new LinkedHashMap<String,Object>(Map.of("stockId",Long.toString(targetStock),"factoryWeight",factoryWeight.toPlainString(),"factoryQuantity",factoryQ,"customerWeight",customerWeight.toPlainString(),"customerQuantity",customerQ,"issueLineId",Long.toString(sourceLine),"sentWeight",sent.toPlainString(),"sentQuantity",sentQuantity,"receivedWeight",returned.toPlainString(),"receivedQuantity",quantity));
        if(residualBatch!=null){new ProductionBatchMaterialService(jdbc).bindResidualSources(factory,event.id(),targetSlice,input,factoryWeight,factoryQ,customerWeight,customerQ,customer);returnedResult.put("residualBatchId",Long.toString(residualBatch));returnedResult.put("sourceBatchId",text(sourceSlice.get("batch_id")));returnedResult.put("stockSliceId",Long.toString(targetSlice));}
        if(input.get("carryAllocationId")!=null){long carry=id(input.get("carryAllocationId")),execution=id(input.get("executionId"));new ProductionBatchMaterialService(jdbc).consumeCarryReturn(factory,carry,execution,sourceLine,sent,sentQuantity,event.id());returnedResult.put("carryAllocationId",Long.toString(carry));returnedResult.put("executionId",Long.toString(execution));}
